def transform(g):
    g=[row[:] for row in g]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    for cells in components(g,bg):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        t,b,l,r=min(ys),max(ys),min(xs),max(xs)
        fill = 2 if (b-t-1,r-l-1)==(2,2) else 7
        for i in range(t+1,b):
            for j in range(l+1,r):
                if g[i][j]==bg: g[i][j]=fill
    return g
